package com.vandorlabs.neoforge.propulsion;

import com.google.gson.*;
import com.vandorlabs.propulsion.*;
import java.nio.file.*;
import net.minecraft.core.Direction;
import net.minecraft.nbt.*;
import net.minecraft.world.phys.Vec3;

/** Released factory poses and actual vanilla item callbacks, not a replacement item implementation. */
public final class PropulsionPlacementChecks {
 private static int checks;
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
 private static void state(JsonObject expected,PropulsionDefinition block,int facing,boolean powered,String label){need(expected.get("id").getAsString().equals(block.id)&&expected.get("facing").getAsInt()==facing&&expected.get("powered").getAsBoolean()==powered&&!expected.get("particles").getAsBoolean(),label+" exact selected state");}
 public static void main(String[] args)throws Exception {
  int poses=0,placements=0;try(var reader=Files.newBufferedReader(Path.of(args[0]))){for(String line;(line=reader.readLine())!=null;){var row=JsonParser.parseString(line).getAsJsonObject();var definition=PropulsionDefinition.of(row.get("block").getAsString());if(row.get("kind").getAsString().equals("pose")){int meta=row.get("meta").getAsInt(),facing=PropulsionPlacement.facing(meta,definition.defaultFacing);boolean powered=PropulsionPlacement.powered(meta);state(row.getAsJsonObject("state"),definition,facing,powered,"pose "+poses);need(PropulsionPlacement.metadata(facing,powered)==row.get("encoded").getAsInt()&&definition.defaultFacing==row.get("defaultFacing").getAsInt()&&definition.shape==row.get("shape").getAsInt()&&definition.family.equals(row.get("family").getAsString())&&(definition.maxConnected>0)==row.get("join").getAsBoolean(),"metadata/factory descriptor");double[] bounds=PropulsionPlacement.bounds(definition.depth,facing);for(int i=0;i<6;i++)need(bounds[i]==row.getAsJsonArray("bounds").get(i).getAsDouble(),"source exact bounds");for(int turn=0;turn<4;turn++){int corner=PropulsionPlacement.rotateCorner(definition.corner,facing,turn);var rotated=definition.shape==2?PropulsionDefinition.of(PropulsionDefinition.wedgeId(definition.family,corner)):definition;state(row.getAsJsonArray("rotations").get(turn).getAsJsonObject(),rotated,PropulsionPlacement.rotateFacing(facing,turn),powered,"rotation");}for(int mirror=0;mirror<3;mirror++){int turns=PropulsionPlacement.mirrorTurns(facing,mirror);state(row.getAsJsonArray("mirrors").get(mirror).getAsJsonObject(),definition,PropulsionPlacement.rotateFacing(facing,turns),powered,"mirror");}poses++;continue;}
   var input=row.get("input").getAsString();var raw=input.isEmpty()?null:TagParser.parseTag(input);var hit=row.getAsJsonArray("hit");int facing=row.get("face").getAsInt();var selected=NativePropulsionPlacement.select(definition.id,raw,Direction.from3DDataValue(facing),new Vec3(hit.get(0).getAsFloat(),hit.get(1).getAsFloat(),hit.get(2).getAsFloat()));state(row.getAsJsonObject("initial"),selected,facing,true,"placement initial "+placements);var placed=row.getAsJsonObject("placed");state(placed,selected,facing,true,"placed");var settings=NativePropulsionPlacement.settings(definition.id,selected.id,row.get("remote").getAsBoolean(),raw);var actual=new CompoundTag();settings.write(actual);var expected=TagParser.parseTag(placed.get("saved").getAsString());for(String key:new String[]{"id","x","y","z"})expected.remove(key);need(actual.equals(expected),"actual fresh-save/shape/client merge "+placements+" expected="+expected+" actual="+actual);var picked=TagParser.parseTag(placed.get("pick").getAsString());need(picked.getString("id").equals("vandorlabs:"+NativePropulsionPlacement.item(selected))&&picked.getByte("Count")==1&&picked.getCompound("tag").getCompound("BlockEntityTag").equals(NativePropulsionPlacement.pick(selected,settings)),"source configured pick");var drops=placed.getAsJsonArray("drops");need(drops.size()==1,"one source item drop");var drop=TagParser.parseTag(drops.get(0).getAsString());need(drop.getString("id").equals("vandorlabs:"+NativePropulsionPlacement.item(selected))&&drop.getByte("Count")==1&&drop.getCompound("tag").getCompound("BlockEntityTag").equals(NativePropulsionPlacement.drop(selected)),"source shape-only drop");placements++;
  }}need(poses==486&&placements==33600,"source coverage");System.out.println("[vandorlabs][propulsion-placement] CPU PASS poses="+poses+" actualCallbacks="+placements+" checks="+checks+" sixface float ties/metadata/rotations/bounds/fresh-save NBT conditional merge/pick-vs-drop; inactive adapter");
 }
}
